-- Shared SayThanks DB (staging): apply LMS migrations to the `lms` schema.
-- Generated by scripts/shared-db/build-lms-bundle.mjs from 032c5ce7..e153d231. Do not edit by hand;
-- regenerate instead. 7 migrations, in order:
--   20261025140000_ai_evals_checkpoint_grader.sql
--   20261025150000_ai_evals_exam_grader.sql
--   20261025160000_ai_evals_exercise_scenarios.sql
--   20261026100000_ai_eval_cases_submission_source.sql
--   20261026110000_exercise_evaluations_answer_and_review.sql
--   20261026120000_exam_questions_sequence.sql
--   20261026121599_fork_tighten_permissive_rls.sql
--
-- Run once, as postgres, in one transaction (any error rolls everything back):
--   docker exec -i saythanks-staging-db-1 psql -U postgres -d postgres -v ON_ERROR_STOP=1 -1 < THIS_FILE
--
-- Shared-schema statements to read before running (storage is used by SayThanks too).
-- They only name LMS buckets or LMS policy names, but triggers on storage.objects fire
-- for every bucket:


\set ON_ERROR_STOP on
SET LOCAL search_path = lms, public, extensions;

-- Preflight: refuse to run against a schema that is not the pre-sync baseline.
-- The ledger query is dynamic SQL: a static reference to a table that does not exist
-- yet fails when PL/pgSQL plans it, even behind a to_regclass() check.
DO $preflight$
DECLARE
  already boolean := false;
BEGIN
  IF to_regclass('lms.tenants') IS NULL THEN
    RAISE EXCEPTION 'lms.tenants not found: wrong database or schema';
  END IF;
  IF to_regclass('lms.lms_migration_log') IS NOT NULL THEN
    EXECUTE 'SELECT EXISTS (SELECT 1 FROM lms.lms_migration_log WHERE version = ANY ($1))'
      INTO already
      USING ARRAY['20261025140000', '20261025150000', '20261025160000', '20261026100000', '20261026110000', '20261026120000', '20261026121599']::text[];
    IF already THEN
      RAISE EXCEPTION 'some of these migrations are already recorded in lms.lms_migration_log';
    END IF;
  END IF;
END
$preflight$;

-- Ledger of what has been applied to the shared schema (the shared DB has no
-- supabase_migrations history for `lms`). Service-only.
CREATE TABLE IF NOT EXISTS lms.lms_migration_log (
  version    text PRIMARY KEY,
  name       text NOT NULL,
  applied_at timestamptz NOT NULL DEFAULT now()
);
REVOKE ALL ON lms.lms_migration_log FROM anon, authenticated;

