-- 2. Exam grader versions --------------------------------------------------------

-- Everything that changes how the grader scores the exam: the questions and
-- options as written, a digest of each question's grading secrets, and the AI
-- config. The answer key itself is NOT copied into the snapshot (only md5
-- digests), so a version row never holds key material twice.
CREATE OR REPLACE FUNCTION lms.exam_grader_config_snapshot(_exam_id bigint)
RETURNS jsonb
LANGUAGE sql STABLE SECURITY DEFINER
SET search_path TO ''
AS $$
  SELECT jsonb_build_object(
    'title', e.title,
    'description', coalesce(e.description, ''),
    'questions', coalesce((
      SELECT jsonb_agg(
        jsonb_build_object(
          'question_id', q.question_id,
          'question_type', q.question_type,
          'question_text', q.question_text,
          'points', q.points,
          'options', coalesce((
            SELECT jsonb_agg(jsonb_build_object('option_id', o.option_id, 'option_text', o.option_text) ORDER BY o.option_id)
              FROM lms.question_options o WHERE o.question_id = q.question_id), '[]'::jsonb),
          'secrets_md5', md5(
            coalesce(s.correct_answer, '') || '|' ||
            coalesce(s.grading_rubric, '') || '|' ||
            coalesce(s.ai_grading_criteria, '') || '|' ||
            coalesce(array_to_string(s.expected_keywords, ','), '') || '|' ||
            coalesce(array_to_string(s.correct_option_ids, ','), ''))
        ) ORDER BY q.question_id)
      FROM lms.exam_questions q
      LEFT JOIN lms.exam_grading_secrets s ON s.question_id = q.question_id
      WHERE q.exam_id = e.exam_id), '[]'::jsonb),
    'ai_config', coalesce((
      SELECT jsonb_build_object(
        'ai_grading_prompt', c.ai_grading_prompt,
        'ai_persona', c.ai_persona,
        'ai_feedback_tone', c.ai_feedback_tone,
        'ai_feedback_detail_level', c.ai_feedback_detail_level)
      FROM lms.exam_ai_configs c WHERE c.exam_id = e.exam_id), '{}'::jsonb)
  )
    FROM lms.exams e
   WHERE e.exam_id = _exam_id;
$$;

REVOKE EXECUTE ON FUNCTION lms.exam_grader_config_snapshot(bigint) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION lms.exam_grader_config_snapshot(bigint) TO service_role;

-- Returns the version for the exam's current grader config, creating it (next
-- version_no) when new. Service role only: callers verify the tenant. Never
-- return the snapshot to a client.
CREATE OR REPLACE FUNCTION lms.ensure_exam_grader_version(_exam_id bigint)
RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER
SET search_path TO ''
AS $$
DECLARE
  _tenant uuid;
  _snapshot jsonb;
  _hash text;
  _id uuid;
BEGIN
  SELECT tenant_id INTO _tenant FROM lms.exams WHERE exam_id = _exam_id;
  IF _tenant IS NULL THEN
    RAISE EXCEPTION 'exam % not found', _exam_id;
  END IF;

  _snapshot := lms.exam_grader_config_snapshot(_exam_id) || jsonb_build_object('grader', 'exam');
  _hash := md5(_snapshot::text);

  SELECT id INTO _id FROM lms.ai_config_versions
   WHERE target_type = 'exam' AND target_id = _exam_id AND config_hash = _hash;
  IF _id IS NOT NULL THEN
    RETURN _id;
  END IF;

  -- Serialise version_no allocation per exam.
  PERFORM pg_advisory_xact_lock(hashtext('ai_config_versions:exam:' || _exam_id));

  INSERT INTO lms.ai_config_versions (tenant_id, target_type, target_id, version_no, config_hash, snapshot)
  SELECT _tenant, 'exam', _exam_id,
         coalesce(max(version_no), 0) + 1, _hash, _snapshot
    FROM lms.ai_config_versions
   WHERE target_type = 'exam' AND target_id = _exam_id
  ON CONFLICT (target_type, target_id, config_hash) DO NOTHING
  RETURNING id INTO _id;

  IF _id IS NULL THEN
    SELECT id INTO _id FROM lms.ai_config_versions
     WHERE target_type = 'exam' AND target_id = _exam_id AND config_hash = _hash;
  END IF;
  RETURN _id;
END;
$$;

REVOKE EXECUTE ON FUNCTION lms.ensure_exam_grader_version(bigint) FROM PUBLIC, anon, authenticated;
GRANT EXECUTE ON FUNCTION lms.ensure_exam_grader_version(bigint) TO service_role;

