-- 20261026100000_ai_eval_cases_submission_source.sql
-- ===========================================================================
-- F5: a case saved from a teacher-reviewed student submission.
-- The expected result is the teacher's own grade, so it counts as verified;
-- the source only records where the answers came from.

ALTER TABLE lms.ai_eval_cases DROP CONSTRAINT ai_eval_cases_source_check;
ALTER TABLE lms.ai_eval_cases ADD CONSTRAINT ai_eval_cases_source_check
  CHECK (source IN ('preview', 'real_chat', 'generated', 'teacher', 'submission'));

-- ===========================================================================
-- 20261026110000_exercise_evaluations_answer_and_review.sql
-- ===========================================================================
-- F5 (exercises): keep what the student submitted, and let a teacher regrade it.
--
-- submission_text / submission_metadata: the answer the AI graded (written and
-- code exercises, artifacts). Older rows stay NULL; nothing was stored before.
-- teacher_*: a teacher's override of that grade. The AI score in `score` is
-- kept as is, so the gap between the two is what a grading test checks.
--
-- Writes stay server-side (service role after a staff check); no UPDATE policy
-- is added. Students already read their own rows, which now includes the
-- teacher's grade and note on them.

ALTER TABLE lms.exercise_evaluations
  ADD COLUMN submission_text text,
  ADD COLUMN submission_metadata jsonb,
  ADD COLUMN teacher_score numeric(5,2) CHECK (teacher_score IS NULL OR (teacher_score >= 0 AND teacher_score <= 100)),
  ADD COLUMN teacher_passed boolean,
  ADD COLUMN teacher_feedback text CHECK (teacher_feedback IS NULL OR char_length(teacher_feedback) <= 5000),
  ADD COLUMN teacher_id uuid REFERENCES auth.users(id) ON DELETE SET NULL,
  ADD COLUMN reviewed_at timestamptz;

CREATE INDEX exercise_evaluations_exercise_recent_idx
  ON lms.exercise_evaluations (tenant_id, exercise_id, created_at DESC);

-- ===========================================================================
-- 20261026120000_exam_questions_sequence.sql
-- ===========================================================================
-- The exam builder used to save by deleting every question of the exam and
-- re-inserting it, so question order was simply question_id order. That
-- delete cascaded to exam_answers, exam_question_scores, exam_grading_secrets
-- and question_options, and gave every question a new id (orphaning the exam
-- grading tests in ai_eval_cases). The builder now updates kept questions in
-- place, so the order the teacher drags them into needs its own column.
--
-- NULL = no position set (questions added by other writers, e.g. the MCP
-- lms_add_exam_question tool): readers order by sequence NULLS LAST, then
-- question_id, which appends them as before.

ALTER TABLE lms.exam_questions ADD COLUMN sequence integer;

COMMENT ON COLUMN lms.exam_questions.sequence IS
  'Position of the question in its exam (1-based). NULL sorts last; ties break on question_id.';

-- A data backfill should not go through the grading-secrets split trigger.
ALTER TABLE lms.exam_questions DISABLE TRIGGER USER;

UPDATE lms.exam_questions q
SET sequence = ranked.rn
FROM (
  SELECT question_id, row_number() OVER (PARTITION BY exam_id ORDER BY question_id) AS rn
  FROM lms.exam_questions
) ranked
WHERE ranked.question_id = q.question_id;

ALTER TABLE lms.exam_questions ENABLE TRIGGER USER;

-- ===========================================================================
-- 20261026121599_fork_tighten_permissive_rls.sql
-- ===========================================================================
-- Tighten the RLS policies that still grant `true` on tenant data.
--
-- A Supabase security scan flagged every policy whose USING / WITH CHECK is a
-- bare `true`. Policies are OR-ed, so one `true` SELECT policy makes the
-- tenant-scoped policies beside it moot: every row is readable by every
-- caller the policy names, in every school.
--
-- Fixed here:
--   profiles               anyone (anon too) could read every profile in every
--                          school, including stripe_customer_id.
--   messages               legacy chat table, unused by the app; anyone could
--                          read it and any signed-in user could write to any chat.
--   assignments            legacy table, unused by the app; any signed-in user
--                          could read every school's assignments.
--   comment_reactions      any signed-in user could read reactions in every school.
--   gamification_profiles  the global leaderboard policy overrode the
--                          per-school one (and leagues_opt_out).
--
-- Left as is on purpose (global reference data or public catalog, no tenant
-- data behind them): roles, permissions, role_permissions, gamification_levels,
-- league_tiers, landing_page_templates, course_categories, product_courses,
-- plan_courses, reviews; user_roles' policy is for supabase_auth_admin (the JWT
-- hook); certificate_verification_log only accepts inserts from the public
-- verify route and has no public read.
--
-- Tables with RLS on and no policies (webhook_events, tenant_ai_credentials,
-- cron_runs, …) are server-only by design: the service role bypasses RLS and
-- everyone else is denied.

-- ─── profiles ──────────────────────────────────────────────────────────────
-- Who may read a profile row besides its owner and super admins:
--   * signed-in members of the school in the caller's JWT, when the profile
--     belongs to that school too (dashboards, comments, community, leaderboards);
--   * anyone, for authors of published courses (public course pages).
-- Both checks read tenant_users / courses, whose own RLS would hide the rows,
-- so they are SECURITY DEFINER helpers.

CREATE OR REPLACE FUNCTION lms.shares_current_tenant(target_user uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $$
  SELECT EXISTS (
    SELECT 1
    FROM lms.tenant_users me
    JOIN lms.tenant_users them ON them.tenant_id = me.tenant_id
    WHERE me.user_id = auth.uid()
      AND me.tenant_id = lms.get_tenant_id()
      AND them.user_id = target_user
  );
$$;

CREATE OR REPLACE FUNCTION lms.is_published_course_author(target_user uuid)
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path TO ''
AS $$
  SELECT EXISTS (
    SELECT 1 FROM lms.courses c
    WHERE c.author_id = target_user AND c.status = 'published'
  );
$$;

REVOKE ALL ON FUNCTION lms.shares_current_tenant(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION lms.is_published_course_author(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION lms.shares_current_tenant(uuid) TO anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION lms.is_published_course_author(uuid) TO anon, authenticated, service_role;

DROP POLICY IF EXISTS "Public profiles are viewable by everyone." ON lms.profiles;
DROP POLICY IF EXISTS "Profiles are visible within the school" ON lms.profiles;
CREATE POLICY "Profiles are visible within the school"
  ON lms.profiles
  FOR SELECT
  TO anon, authenticated
  USING (
    id = (SELECT auth.uid())
    OR (SELECT lms.is_super_admin())
    OR ((SELECT auth.uid()) IS NOT NULL AND lms.shares_current_tenant(id))
    OR lms.is_published_course_author(id)
  );

-- ─── messages (legacy, unused) ─────────────────────────────────────────────
-- "Tenant admins can manage their members' messages" stays.
DROP POLICY IF EXISTS "Enable read access for all users" ON lms.messages;
DROP POLICY IF EXISTS "Authenticated users can create messages" ON lms.messages;

-- ─── assignments (legacy, unused) ──────────────────────────────────────────
-- "Tenant staff can manage tenant assignments" stays.
DROP POLICY IF EXISTS "Authenticated users can view assignments" ON lms.assignments;

-- ─── comment_reactions ─────────────────────────────────────────────────────
-- A reaction is visible when its comment is; the subquery runs under the
-- caller's lesson_comments RLS.
DROP POLICY IF EXISTS "Authenticated users can view comment reactions" ON lms.comment_reactions;
DROP POLICY IF EXISTS "Users can view reactions on readable comments" ON lms.comment_reactions;
CREATE POLICY "Users can view reactions on readable comments"
  ON lms.comment_reactions
  FOR SELECT
  TO authenticated
  USING (
    EXISTS (SELECT 1 FROM lms.lesson_comments c WHERE c.id = comment_reactions.comment_id)
  );

-- ─── gamification_profiles ─────────────────────────────────────────────────
