-- Functions created with a public search_path elsewhere still need lms first (same as
-- supabase/shared-db/lms-schema-search-path.sql).
DO $fix$
DECLARE r record;
BEGIN
  FOR r IN
    SELECT p.oid::regprocedure AS sig
    FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace
    WHERE n.nspname = 'lms' AND p.proconfig @> ARRAY['search_path=public']
  LOOP
    EXECUTE 'ALTER FUNCTION ' || r.sig || ' SET search_path = lms, public';
  END LOOP;
END
$fix$;

NOTIFY pgrst, 'reload schema';
